# Example memoization usage in Python for a recursive function
def memoize(func):
    cache = {}
    def memoized_func(*args):
        if args in cache:
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result
    return memoized_func

@memoize
def soc(a):
    if a == 0:
        return 0
    elif a == 1:
        return 1
    else:
        return soc(a-1) + soc(a-2)
